一、实例与数据库基础（1–20）

查看实例身份、版本、启动时间与 DSC 角色：SELECT NAME, INSTANCE_NAME, INSTANCE_NUMBER, HOST_NAME, DB_VERSION, START_TIME, STATUS$, MODE$, DSC_ROLE FROM V$INSTANCE;
查看数据库角色、状态、归档模式与容量：SELECT NAME, ROLE$, STATUS$, ARCH_MODE, DSC_NODES, TOTAL_SIZE, MAX_SIZE, CREATE_TIME, LAST_STARTUP_TIME FROM V$DATABASE;
查看实例名、主机、版本与编译信息：SELECT INSTANCE_NAME, HOST_NAME, DB_VERSION, BUILD_VERSION, BUILD_TIME FROM V$INSTANCE;
计算实例已运行天数：SELECT NAME, START_TIME, ROUND((SYSDATE - START_TIME), 2) AS RUN_DAYS FROM V$INSTANCE;
查看打开次数、启动次数与最后检查点：SELECT NAME, OPEN_COUNT, STARTUP_COUNT, LAST_CKPT_TIME FROM V$DATABASE;
查看主机 CPU 数与负载均值：SELECT N_CPU, CPU_USER_RATE, CPU_SYSTEM_RATE, CPU_IDLE_RATE, LOAD_ONE_AVERAGE, LOAD_FIVE_AVERAGE, LOAD_FIFTEEN_AVERAGE FROM V$SYSTEMINFO;
查看主机物理/虚拟内存总量与剩余：SELECT TOTAL_PHY_SIZE, USED_PHY_SIZE, FREE_PHY_SIZE, TOTAL_VIR_SIZE, FREE_VIR_SIZE FROM V$SYSTEMINFO;
查看磁盘总量、剩余与挂载设备：SELECT TOTAL_DISK_SIZE, FREE_DISK_SIZE, DRIVER_NAME, DRIVER_TOTAL_SIZE, DRIVER_FREE_SIZE FROM V$SYSTEMINFO;
查看实例网络累计收发与实时速率：SELECT RECEIVE_BYTES_TOTAL, SEND_BYTES_TOTAL, RECEIVE_BYTES_PER_SECOND, SEND_BYTES_PER_SECOND FROM V$SYSTEMINFO;
查看实例网络收发字节原值：SELECT RECV_BYTES, SEND_BYTES FROM V$NETINFO;
核对授权到期日与连接、CPU、核心数上限：SELECT EXPIRED_DATE, PRODUCT_TYPE, SERVER_TYPE, MAX_CPU_NUM, MAX_CORE_NUM, AUTHORIZED_USER_NUMBER, CONCURRENCY_USER_NUMBER FROM V$LICENSE;
核对授权空间与表记录数上限：SELECT EXPIRED_DATE, TOTAL_SPACE_LIMIT, TABLE_RECORD_NUMBER_LIMIT FROM V$LICENSE;
查看授权客户、项目、硬件与操作系统类型：SELECT AUTHORIZED_CUSTOMER, PROJECT_NAME, HARDWARE_TYPE, OS_TYPE, DATE_GEN FROM V$LICENSE;
查看实例打开模式与主备身份历史：SELECT SYS_MODE, OPEN_TIME, CUR_INST_NAME, PRIMARY_INST_NAME, N_EP FROM SYSOPENHISTORY ORDER BY OPEN_TIME DESC;
查看最近的重要管理操作与操作人：SELECT OPUSER, OPTIME, OPERATION FROM V$DANGER_EVENT ORDER BY OPTIME DESC;
查看参数运行值、系统值、文件值与默认值：SELECT NAME, VALUE, SYS_VALUE, FILE_VALUE, DEFAULT_VALUE, ISDEFAULT FROM V$PARAMETER;
对比参数会话值、运行值与文件值：SELECT PARA_NAME, PARA_VALUE, SESS_VALUE, FILE_VALUE, DEFAULT_VALUE, PARA_TYPE FROM V$DM_INI;
筛��内存相关参数及其上下限：SELECT PARA_NAME, PARA_VALUE, DEFAULT_VALUE, MIN_VALUE, MAX_VALUE FROM V$DM_INI WHERE PARA_NAME LIKE '%MEM%';
筛选时间类参数当前值：SELECT PARA_NAME, PARA_VALUE, DEFAULT_VALUE FROM V$DM_INI WHERE PARA_NAME LIKE '%TIME%';
筛选归档相关参数当前值：SELECT PARA_NAME, PARA_VALUE, DEFAULT_VALUE FROM V$DM_INI WHERE PARA_NAME LIKE '%ARCH%';

二、会话管理（21–65）

列出全部会话及来源主机、应用：SELECT SESS_ID, USER_NAME, CLNT_IP, CLNT_HOST, APPNAME, STATE, CREATE_TIME FROM V$SESSIONS ORDER BY CREATE_TIME;
定位当前活动会话：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE, SQL_ID FROM V$SESSIONS WHERE STATE = 'ACTIVE';
查看非空闲会话及其事务与 SQL：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE, TRX_ID, SQL_TEXT FROM V$SESSIONS WHERE STATE <> 'IDLE';
按状态统计会话数：SELECT STATE, COUNT(*) AS SESS_CNT FROM V$SESSIONS GROUP BY STATE ORDER BY SESS_CNT DESC;
按用户统计会话数：SELECT USER_NAME, COUNT(*) AS SESS_CNT FROM V$SESSIONS GROUP BY USER_NAME ORDER BY SESS_CNT DESC;
按客户端 IP 统计连接数：SELECT CLNT_IP, COUNT(*) AS SESS_CNT FROM V$SESSIONS GROUP BY CLNT_IP ORDER BY SESS_CNT DESC;
按应用名统计连接数：SELECT APPNAME, COUNT(*) AS SESS_CNT FROM V$SESSIONS GROUP BY APPNAME ORDER BY SESS_CNT DESC;
按客户端类型统计连接数：SELECT CLNT_TYPE, COUNT(*) AS SESS_CNT FROM V$SESSIONS GROUP BY CLNT_TYPE ORDER BY SESS_CNT DESC;
计算会话已连接小时数：SELECT SESS_ID, USER_NAME, CLNT_IP, CREATE_TIME, ROUND((SYSDATE - CREATE_TIME) * 24, 2) AS CONN_HOURS FROM V$SESSIONS ORDER BY CREATE_TIME;
按最后接收时间排查挂起会话：SELECT SESS_ID, USER_NAME, CLNT_IP, LAST_RECV_TIME FROM V$SESSIONS ORDER BY LAST_RECV_TIME;
按最后发送时间排查挂起会话：SELECT SESS_ID, USER_NAME, CLNT_IP, LAST_SEND_TIME FROM V$SESSIONS ORDER BY LAST_SEND_TIME;
查看会话已用语句槽数量：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE, N_USED_STMT FROM V$SESSIONS ORDER BY N_USED_STMT DESC;
查看会话临时段占用：SELECT SESS_ID, USER_NAME, CLNT_IP, TMP_USED_EXTENT_NUM, TMP_USED_TYPE FROM V$SESSIONS WHERE TMP_USED_EXTENT_NUM > 0 ORDER BY TMP_USED_EXTENT_NUM DESC;
查看会话当前模式与执行语句：SELECT SESS_ID, USER_NAME, CURR_SCH, STATE, SQL_TEXT FROM V$SESSIONS WHERE CURR_SCH IS NOT NULL;
查看自动提交、隔离级别与连接状态：SELECT SESS_ID, USER_NAME, AUTO_CMT, ISO_LEVEL, CONNECTED FROM V$SESSIONS;
查看客户端操作系统与驱动版本：SELECT SESS_ID, USER_NAME, OSNAME, CLNT_VER, CLNT_TYPE FROM V$SESSIONS;
查看会话模块、动作与客户端标识：SELECT SESS_ID, USER_NAME, MODULE, ACTION, CLIENT_INFO FROM V$SESSIONS WHERE MODULE IS NOT NULL;
查看会话线程号、序列号与事务号：SELECT SESS_ID, USER_NAME, THRD_ID, SESS_SEQ, TRX_ID FROM V$SESSIONS;
查看会话正在执行的 SQL_ID：SELECT SESS_ID, USER_NAME, SQL_ID, SQL_TEXT FROM V$SESSIONS WHERE SQL_ID IS NOT NULL;
查看存储过程内当前 SQL 片段：SELECT SESS_ID, USER_NAME, CLNT_IP, CUR_SQLSTR FROM V$SESSIONS WHERE CUR_SQLSTR IS NOT NULL;
查看存储过程当前方法名与行号：SELECT SESS_ID, USER_NAME, CUR_MTDNAME, CUR_LINENO FROM V$SESSIONS WHERE CUR_MTDNAME IS NOT NULL;
查看会话时区设置：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE, TIME_ZONE FROM V$SESSIONS;
查看会话运行状态标记：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE, RUN_STATUS FROM V$SESSIONS;
查看会话查询只读属性：SELECT SESS_ID, USER_NAME, CLNT_IP, RS_FOR_QRY, RDONLY FROM V$SESSIONS;
查看 DCP 登录与端口类型：SELECT SESS_ID, USER_NAME, CLNT_IP, DCP_FLAG, PORT_TYPE FROM V$SESSIONS;
查看会话心跳间隔与超时设置：SELECT SESS_ID, USER_NAME, CLNT_IP, HEART_BEAT_INTERVAL, HEART_BEAT_TIMEOUT FROM V$SESSIONS;
查看会话消息收发状态：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE, MSG_STATUS FROM V$SESSIONS;
查看会话全局 ID 与 MAL 站点：SELECT SESS_ID, USER_NAME, CLNT_IP, EID, MAL_ID, SRC_SITE FROM V$SESSIONS;
查看会话约束、自增列与网络检查开关：SELECT SESS_ID, USER_NAME, CLNT_IP, CHK_CONS, CHK_IDENT, CHK_NET FROM V$SESSIONS;
查看空值插入、编译与 DDL 自动提交开关：SELECT SESS_ID, USER_NAME, CLNT_IP, INS_NULL, COMPILE_FLAG, DDL_AUTOCMT FROM V$SESSIONS;
查看限流占用与语句容量：SELECT SESS_ID, USER_NAME, CLNT_IP, CONCURRENT_FLAG, N_STMT FROM V$SESSIONS;
查看应用设置的客户端标识信息：SELECT SESS_ID, USER_NAME, CLNT_IP, CLIENT_IDENTIFIER, CLIENT_INFO FROM V$SESSIONS;
查看会话序号与私有内存池地址：SELECT SESS_ID, USER_NAME, CLNT_IP, SEQ_NO, VPOOLADDR FROM V$SESSIONS;
查找空闲超过一天的接收挂起会话：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE FROM V$SESSIONS WHERE STATE = 'IDLE' AND LAST_RECV_TIME < (SYSDATE - 1);
查找空闲超过一天的发送挂起会话：SELECT SESS_ID, USER_NAME, CLNT_IP, STATE FROM V$SESSIONS WHERE STATE = 'IDLE' AND LAST_SEND_TIME < (SYSDATE - 1);
按用户与状态交叉统计会话：SELECT USER_NAME, STATE, COUNT(*) AS CNT FROM V$SESSIONS GROUP BY USER_NAME, STATE ORDER BY USER_NAME, STATE;
按客户端主机与 IP 统计连接：SELECT CLNT_HOST, CLNT_IP, COUNT(*) AS CNT FROM V$SESSIONS GROUP BY CLNT_HOST, CLNT_IP ORDER BY CNT DESC;
按应用与用户统计连接分布：SELECT APPNAME, USER_NAME, COUNT(*) AS CNT FROM V$SESSIONS GROUP BY APPNAME, USER_NAME ORDER BY CNT DESC;
DSC 各节点按状态统计会话：SELECT INSTANCE_NAME, STATE, COUNT(*) AS CNT FROM GV$SESSIONS GROUP BY INSTANCE_NAME, STATE ORDER BY INSTANCE_NAME, STATE;
DSC 各节点按用户统计会话：SELECT INSTANCE_NAME, USER_NAME, COUNT(*) AS CNT FROM GV$SESSIONS GROUP BY INSTANCE_NAME, USER_NAME ORDER BY CNT DESC;
DSC 查看各节点活动会话明细：SELECT INSTANCE_NAME, SESS_ID, USER_NAME, CLNT_IP, STATE FROM GV$SESSIONS WHERE STATE = 'ACTIVE';
DSC 各节点按应用统计连接：SELECT INSTANCE_NAME, APPNAME, COUNT(*) AS CNT FROM GV$SESSIONS GROUP BY INSTANCE_NAME, APPNAME ORDER BY CNT DESC;
DSC 各节点按客户端 IP 统计连接：SELECT INSTANCE_NAME, CLNT_IP, COUNT(*) AS CNT FROM GV$SESSIONS GROUP BY INSTANCE_NAME, CLNT_IP ORDER BY CNT DESC;
汇总总会话、活动与空闲会话数：SELECT COUNT(*) AS TOTAL_SESS, SUM(CASE WHEN STATE = 'ACTIVE' THEN 1 ELSE 0 END) AS ACTIVE_SESS, SUM(CASE WHEN STATE = 'IDLE' THEN 1 ELSE 0 END) AS IDLE_SESS FROM V$SESSIONS;
找出连接数超过 50 的用户：SELECT USER_NAME, COUNT(*) AS CNT FROM V$SESSIONS GROUP BY USER_NAME HAVING COUNT(*) > 50 ORDER BY CNT DESC;

三、锁、阻塞与死锁（66–105）

查看全部锁记录及被阻塞标志：SELECT TRX_ID, TABLE_ID, LMODE, BLOCKED, TID, ROW_IDX FROM V$LOCK ORDER BY TRX_ID;
定位被阻塞的锁记录：SELECT TRX_ID, TABLE_ID, LMODE, BLOCKED FROM V$LOCK WHERE BLOCKED = 1;
按锁类型与模式统计锁数量：SELECT LTYPE, LMODE, COUNT(*) AS CNT FROM V$LOCK GROUP BY LTYPE, LMODE ORDER BY CNT DESC;
按事务统计持锁数量：SELECT TRX_ID, COUNT(*) AS LOCK_CNT FROM V$LOCK GROUP BY TRX_ID ORDER BY LOCK_CNT DESC;
按对象统计锁竞争次数：SELECT TABLE_ID, COUNT(*) AS CNT FROM V$LOCK GROUP BY TABLE_ID ORDER BY CNT DESC;
查看排他级及以上锁：SELECT ADDR, TABLE_ID, TID, LMODE, BLOCKED FROM V$LOCK WHERE LMODE >= 5;
